// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0 <0.9.0;

// Interfaz para comunicarse con nuestro token ERC20
interface IERC20 {
    function transfer(address to, uint256 value)
        external returns (bool);

    function transferFrom(
        address from,
        address to,
        uint256 value
    ) external returns (bool);

    function balanceOf(address account)
        external view returns (uint256);
}

contract Escrow {

    // Estados posibles de una orden
    enum Status {
        Created,
        Paid,
        Completed,
        Refunded,
        Disputed
    }

    // Información de cada orden
    struct Order {
        address buyer;
        address seller;
        address token;
        uint256 amount;
        uint256 deadline;
        Status status;
        string description;
    }

    // Almacenamiento
    address public arbiter;
    uint256 public orderCount;

    mapping(uint256 => Order) private _orders;

    // Eventos
    event OrderCreated(
        uint256 indexed id,
        address indexed buyer,
        address indexed seller,
        address token,
        uint256 amount,
        uint256 deadline
    );

    event OrderPaid(uint256 indexed id);
    event OrderCompleted(uint256 indexed id);
    event OrderRefunded(uint256 indexed id);

    event OrderDisputed(
        uint256 indexed id,
        address by
    );

    event OrderResolved(
        uint256 indexed id,
        bool sellerWins
    );

    // Modificadores
    modifier onlyArbiter() {
        require(
            msg.sender == arbiter,
            "Escrow: caller is not the arbiter"
        );
        _;
    }

    modifier onlyBuyer(uint256 id) {
        require(
            msg.sender == _orders[id].buyer,
            "Escrow: caller is not the buyer"
        );
        _;
    }

    modifier inStatus(uint256 id, Status s) {
        require(
            _orders[id].status == s,
            "Escrow: wrong status"
        );
        _;
    }

    constructor(address _arbiter) {
        require(
            _arbiter != address(0),
            "Escrow: arbiter is the zero address"
        );

        arbiter = _arbiter;
    }

    function getOrder(uint256 id)
        public
        view
        returns (Order memory)
    {
        require(
            id < orderCount,
            "Escrow: order does not exist"
        );

        return _orders[id];
    }
// TODO 1: Crear una orden
function createOrder(
    address seller,
    address token,
    uint256 amount,
    uint256 deadline,
    string memory description
) public returns (uint256) {

    require(
        seller != address(0),
        "Escrow: invalid seller"
    );

    require(
        seller != msg.sender,
        "Escrow: buyer cannot be seller"
    );

    require(
        token != address(0),
        "Escrow: invalid token"
    );

    require(
        amount > 0,
        "Escrow: amount must be positive"
    );

    require(
        deadline > block.timestamp,
        "Escrow: deadline must be in the future"
    );

    uint256 id = orderCount;

    _orders[id] = Order({
        buyer: msg.sender,
        seller: seller,
        token: token,
        amount: amount,
        deadline: deadline,
        status: Status.Created,
        description: description
    });

    orderCount++;

    emit OrderCreated(
        id,
        msg.sender,
        seller,
        token,
        amount,
        deadline
    );

    return id;
}
// TODO 2: Pago del comprador
function deposit(uint256 id)
    public
    onlyBuyer(id)
    inStatus(id, Status.Created)
{
    Order storage o = _orders[id];

    // Cambiar el estado a Paid
    o.status = Status.Paid;

    // Transferir los tokens del comprador a Escrow
    bool success = IERC20(o.token).transferFrom(
        msg.sender,
        address(this),
        o.amount
    );

    require(
        success,
        "Escrow: token transfer failed"
    );

    // Registrar el evento
    emit OrderPaid(id);
}
// TODO 3: Confirmar recepción
function confirm(uint256 id)
    public
    onlyBuyer(id)
    inStatus(id, Status.Paid)
{
    Order storage o = _orders[id];

    // Cambiar el estado a Completed
    o.status = Status.Completed;

    // Transferir los tokens al vendedor
    bool success = IERC20(o.token).transfer(
        o.seller,
        o.amount
    );

    require(
        success,
        "Escrow: token transfer failed"
    );

    emit OrderCompleted(id);
}


// TODO 4: Devolución después del plazo
function refund(uint256 id)
    public
    onlyBuyer(id)
    inStatus(id, Status.Paid)
{
    Order storage o = _orders[id];

    // Comprobar que se haya superado el plazo
    require(
        block.timestamp > o.deadline,
        "Escrow: deadline not reached"
    );

    // Cambiar el estado a Refunded
    o.status = Status.Refunded;

    // Devolver los tokens al comprador
    bool success = IERC20(o.token).transfer(
        o.buyer,
        o.amount
    );

    require(
        success,
        "Escrow: token transfer failed"
    );

    emit OrderRefunded(id);
}


// TODO 5: Abrir una disputa
function dispute(uint256 id)
    public
    inStatus(id, Status.Paid)
{
    Order storage o = _orders[id];

    // Solo el comprador o vendedor pueden abrir una disputa
    require(
        msg.sender == o.buyer || msg.sender == o.seller,
        "Escrow: caller is not buyer or seller"
    );

    // Cambiar el estado a Disputed
    o.status = Status.Disputed;

    emit OrderDisputed(id, msg.sender);
}


// TODO 6: Resolver una disputa
function resolve(uint256 id, bool sellerWins)
    public
    onlyArbiter
    inStatus(id, Status.Disputed)
{
    Order storage o = _orders[id];

    if (sellerWins) {

        // El vendedor gana la disputa
        o.status = Status.Completed;

        bool success = IERC20(o.token).transfer(
            o.seller,
            o.amount
        );

        require(
            success,
            "Escrow: token transfer failed"
        );

    } else {

        // El comprador gana la disputa
        o.status = Status.Refunded;

        bool success = IERC20(o.token).transfer(
            o.buyer,
            o.amount
        );

        require(
            success,
            "Escrow: token transfer failed"
        );
    }

    emit OrderResolved(id, sellerWins);
}
}

